  mutate(
    Tool1 = gsub("optitype", "Optitype-DNA", Tool1),
    Tool2 = gsub("optitype", "Optitype-DNA", Tool2)
  ) %>%
  split(.$Gene) %>%
  lapply(make_concordance_matrix) %>%
  bind_rows()

