per_tool_concordance_weighted <- concordance_df_clean_for_weighted %>%
  tidyr::pivot_longer(
    cols = c(Tool1, Tool2),
    names_to = "role",
    values_to = "Tool"
  ) %>%
  group_by(Gene, Tool) %>%
  summarise(
    Mean_Concordance = weighted.mean(Concordance, w = N, na.rm = TRUE),
    Total_Comparisons = sum(N),
    N_pairs = n(),
    .groups = "drop"
  )
